#!/bin/sh
set -eu
[ "$(id -u)" = 0 ] || { echo 'Root required' >&2; exit 1; }
. /etc/os-release
[ "${ID:-}:${VERSION_ID:-}:$(uname -m)" = ubuntu:24.04:x86_64 ] || { echo 'Ubuntu24.04 amd64 required' >&2; exit 1; }
printf '%s\n' 'VPS TEST: GitHub HTTPS/Ubuntu CA first trust; no detached signature. Preparing official Ubuntu Python/runtime. OS packages may remain after cancellation.'
/usr/bin/apt-get -o Acquire::AllowInsecureRepositories=false -o Acquire::AllowDowngradeToInsecureRepositories=false -o APT::Get::AllowUnauthenticated=false update
/usr/bin/apt-get -o Acquire::AllowInsecureRepositories=false -o APT::Get::AllowUnauthenticated=false -y --no-install-recommends install python3 python3-venv ca-certificates
exec /usr/bin/env -i PATH=/usr/sbin:/usr/bin:/sbin:/bin LANG=C.UTF-8 /usr/bin/python3 -I -B -c 'import base64,gzip;exec(compile(gzip.decompress(base64.b64decode('"'"''"'"')),"HTTPS_TRUSTED_CAPSULE","exec"))'
